export function SkillCard({ title, skills }) {
  return (
    <article className="skills__content">
      <h3 className="skills_title">{title}</h3>
      <ul className="skills__group">
        {skills.map(([name, level]) => (
          <li className="skills__data" key={name}>
            <i className="bx bx-badge-check" aria-hidden="true"></i>
            <span>
              <span className="skills_name">{name}</span>
              <span className="skills__level">{level}</span>
            </span>
          </li>
        ))}
      </ul>
    </article>
  );
}
